import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BqDA2HS7.js";const p=JSON.parse('{"title":"运行记录与图形","description":"","frontmatter":{},"headers":[],"relativePath":"traces.md","filePath":"traces.md"}'),o={name:"traces.md"};function i(l,t,h,n,c,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="运行记录与图形" tabindex="-1">运行记录与图形 <a class="header-anchor" href="#运行记录与图形" aria-label="Permalink to &quot;运行记录与图形&quot;">​</a></h1><p>记录既用于排查一次任务，也用于核对模型路由是否符合策略。不同记录可以收合， 保留开始时间与执行耗时，避免多次任务混在一起难以查找。</p><h2 id="两个页签" tabindex="-1">两个页签 <a class="header-anchor" href="#两个页签" aria-label="Permalink to &quot;两个页签&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页签</th><th>主要内容</th></tr></thead><tbody><tr><td>任务 DAG</td><td>自动路由计划、节点与连线、依赖、模型分配和执行状态</td></tr><tr><td>路由轨迹</td><td>模型调用流程、策略原因、Judge、接受／丢弃、费用与停止原因</td></tr></tbody></table><p>自动路由也有可审计的调用记录与轨迹。Direct 可以没有任务节点图；规划失败可能只有规划调用， 不能因为没有 DAG 就丢失费用或错误。</p><h2 id="每次记录应该看什么" tabindex="-1">每次记录应该看什么 <a class="header-anchor" href="#每次记录应该看什么" aria-label="Permalink to &quot;每次记录应该看什么&quot;">​</a></h2><ol><li>展开本次记录，核对开始时间、总耗时与当前／最终状态。</li><li>图形中选择节点或调用，查看真实 provider、模型、推理等级及用途。</li><li>核对模型选择、保持、恢复、返工或接管的原因。</li><li>查看实际工具证据、原始 Judge 结论、规则版本与实验标识。</li><li>查看本次与累计参考／现金费用、未派发保护及待核对预留。</li></ol><p>模型首字时间、审核等待与用户首次实际看到文字的时间不同：待审核候选已经有 token， 不表示用户已经获得可交付答案。图形与记录随运行事件更新，旧记录缺字段不使用今天的设置补写。</p><h2 id="状态的含义" tabindex="-1">状态的含义 <a class="header-anchor" href="#状态的含义" aria-label="Permalink to &quot;状态的含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>解释</th></tr></thead><tbody><tr><td>运行中／等待审核</td><td>路由尚未形成可交付终态</td></tr><tr><td>已完成</td><td>冻结执行流程完成；独立质量结果另看</td></tr><tr><td>跳过审核</td><td>命中策略跳过条件，不等于独立质量通过</td></tr><tr><td>已接受／已丢弃</td><td>候选是否交给宿主；丢弃调用仍记账</td></tr><tr><td>未审定停止</td><td>证据或审核不足，候选没有正常交付</td></tr><tr><td>待核对</td><td>已派发但结果／用量不明，保留预留</td></tr></tbody></table><h2 id="费用看起来不对时" tabindex="-1">费用看起来不对时 <a class="header-anchor" href="#费用看起来不对时" aria-label="Permalink to &quot;费用看起来不对时&quot;">​</a></h2><p>先区分参考估值与现金，再核对 token 计价单位、缓存互斥、推理 token 是否重复相加、 真实提供方、价目表版本和失败尝试。订阅参考值不能直接当作实际账单。 不要删除错误记录、清零待核对预留或只统计最终成功那次调用。</p><h2 id="本地记录" tabindex="-1">本地记录 <a class="header-anchor" href="#本地记录" aria-label="Permalink to &quot;本地记录&quot;">​</a></h2><p>DSH 插件保存到配置的 <code>runsDir</code>；默认工作目录中的 <code>.refractagent/runs</code>。 独立网关使用启动时指定的 <code>--runs-dir</code>。审计材料可能包含任务上下文，应保存在合适的本地权限下。 导出公开报告时不包含凭证或原始私有会话。</p>',14)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
